import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.position.set(-2.5, 1.6, 0);

  // Load GLB mesh (gear) – async, added to group when ready
  let loadCancelled = false;
  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      if (!loadCancelled) {
        const mesh = gltf.scene;
        group.add(mesh);
      }
    });
  }

  // Local rim light with accent hue (red) to highlight machined metal
  const rimLight = new ctx.THREE.DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-1, 2, 2);
  group.add(rimLight);

  // Interactive handlers: hover lift (0.15 units) + press-down on click
  group.userData.handlers = {
    mouseenter: () => {
      gsap.to(group.position, {
        y: 0.15,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    mouseleave: () => {
      gsap.to(group.position, {
        y: 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    mousedown: () => {
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
    },
    mouseup: () => {
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'back.out',
        overwrite: 'auto',
      });
    },
    click: () => {
      ctx.emit('hub-home.select', {});
    },
  };

  // Apply cinematic primitive: parallax-scroll
  const primResult = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.25,
  });

  // Cleanup: cancel loading, kill GSAP tweens, dispose primitive
  group.userData.cleanup = () => {
    loadCancelled = true;
    if (primResult && primResult.cleanup) primResult.cleanup();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
  };

  return group;
}
